'use strict';
const assert=require('node:assert/strict');
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const OBJECTIVE='ss_mail_agent_cross_persona_read';
const SCOPE='V11 genuine foreign-persona merchant.mail_detail, learner-visible body, canonical Judge/progress, saved GET, fixed/sibling/reset fences';
const FLAGS=Object.freeze(['isolatedStores','fixtureLocalCandidateAdmission','physicalForeignDetail','originalModelEvidence','learnerVisibleBody','physicalAssessment','retainedPacketBound','canonicalJudgeCredit','durableProgress','savedGetNoReplay','fixedPhysicalMailboxDenial','fixedIneligible','siblingDenied','resetFenced','immutableHistory','fixtureCleaned','passed']);
const exact=(v,k)=>v&&Object.getPrototypeOf(v)===Object.prototype&&Object.keys(v).sort().join(',')===[...k].sort().join(',');
function identity(v){assert(exact(v,['shopUserId','sessionId','requestId']));assert(Number.isSafeInteger(v.shopUserId)&&v.shopUserId>0);assert.match(v.sessionId,UUID);assert.match(v.requestId,UUID);return v;}
function reference(v){assert(exact(v,['version','shopUserId','sessionId','requestId','startedAt']));assert.equal(v.version,1);identity({shopUserId:v.shopUserId,sessionId:v.sessionId,requestId:v.requestId});assert(Number.isSafeInteger(v.startedAt)&&v.startedAt>0);return v;}
function dto(v,{saved=false}={}){if(v?.status){const unavailable=v.status==='unavailable';assert(exact(v,unavailable?['completed','status','modelEvaluated','reason']:['completed','status','modelEvaluated']));assert.equal(v.completed,false);assert.equal(v.modelEvaluated,false);assert(['ineligible','unconfirmed','unavailable'].includes(v.status));if(unavailable)assert.equal(v.reason,'evidence_size_limit');return v;}assert(exact(v,['completed','judgment','replayed']));assert.equal(typeof v.completed,'boolean');assert.equal(typeof v.replayed,'boolean');if(saved)assert.equal(v.replayed,true);assert(exact(v.judgment,['verdict','evaluationId','canRetry']));assert(['pass','fail','inconclusive','unavailable'].includes(v.judgment.verdict));assert.match(v.judgment.evaluationId,UUID);assert.equal(typeof v.judgment.canRetry,'boolean');if(v.completed)assert.equal(v.judgment.verdict,'pass');return v;}
async function json(response,options){assert(response&&typeof response.ok==='function'&&response.ok()===true);assert.match(response.headers()['content-type']||'',/^application\/json(?:;|$)/i);return dto(await response.json(),options);}
function createV11AssessmentActions({page,frame,requestFrame,origin,readAssessmentReference,timeout=120000}={}){assert.equal(typeof readAssessmentReference,'function');assert(page?.waitForRequest&&page?.waitForResponse&&requestFrame&&new URL(origin).origin===origin);const active=async()=>{const value=typeof frame==='function'?await frame():frame;assert(value?.waitForFunction,'Active Puppeteer frame required');return value;};const activeRequestFrame=()=>typeof requestFrame==='function'?requestFrame():requestFrame;const matches=(value,method,path)=>{const req=typeof value.request==='function'?value.request():value,u=new URL(req.url());return req.frame()===activeRequestFrame()&&req.method()===method&&u.origin===origin&&u.pathname===path;};let recovery=null;
 const button=async label=>{const f=await active();const attached=await f.waitForFunction(text=>{const nodes=[...document.querySelectorAll('button')].filter(n=>n.textContent.trim()===text&&!n.disabled&&n.getClientRects().length);return nodes.length===1?nodes[0]:null;},{timeout:30000},label);let hitReady;try{const element=attached.asElement();assert(element,`One visible enabled ${label} button required`);await element.evaluate(node=>node.scrollIntoView({block:'center',behavior:'instant'}));hitReady=await f.waitForFunction(node=>{if(!node.isConnected||node.disabled||!node.getClientRects().length)return false;const box=node.getBoundingClientRect(),hit=document.elementFromPoint(box.left+box.width/2,box.top+box.height/2);return hit===node||node.contains(hit);},{timeout:30000},element);await element.click();}finally{await hitReady?.dispose();await attached.dispose();}};
 const capture=async(method,path,click,atRequest)=>{let seen=0;const listener=v=>{if(matches(v,method,path))seen++;};page.on('request',listener);const requestTask=page.waitForRequest(v=>matches(v,method,path),{timeout}),responseTask=page.waitForResponse(v=>matches(v,method,path),{timeout});requestTask.catch(()=>{});responseTask.catch(()=>{});const observed=requestTask.then(req=>atRequest?.(req));observed.catch(()=>{});const clickTask=Promise.resolve().then(click);clickTask.catch(()=>{});try{const[req,,snapshot]=await Promise.all([requestTask,clickTask,observed]);const res=await responseTask;assert.equal(res.request(),req);assert.equal(seen,1);return{request:req,response:res,value:await json(res,{saved:method==='GET'}),snapshot};}finally{page.off('request',listener);requestTask.catch(()=>{});responseTask.catch(()=>{});observed.catch(()=>{});clickTask.catch(()=>{});}};
 return Object.freeze({
  async visibleBody(body){const f=await active();await f.waitForFunction(text=>[...document.querySelectorAll('[aria-label="Merchant saved mail read"] pre')].some(n=>n.textContent===text&&n.getClientRects().length),{timeout:30000},body);return true;},
  async assess(expected){identity(expected);assert.equal(await readAssessmentReference(),null);const wire=await capture('POST','/api/secureshop/agents/merchant/assistant/mail-read/assess',()=>button('Assess agent-selected mail'),()=>readAssessmentReference());const saved=reference(wire.snapshot);assert.deepEqual({shopUserId:saved.shopUserId,sessionId:saved.sessionId,requestId:saved.requestId},expected);assert.deepEqual(JSON.parse(wire.request.postData()),{sessionId:expected.sessionId,requestId:expected.requestId});return wire;},
  armReload(expected){assert.equal(recovery,null);const path=`/api/secureshop/agents/merchant/assistant/mail-read/assessment/${expected.sessionId}/${expected.requestId}`;let seen=0;const matchesGet=value=>matches(value,'GET',path),listener=value=>{if(matchesGet(value))seen++;};page.on('request',listener);const requestTask=page.waitForRequest(matchesGet,{timeout}),responseTask=page.waitForResponse(matchesGet,{timeout});requestTask.catch(()=>{});responseTask.catch(()=>{});const snapshotTask=requestTask.then(()=>readAssessmentReference());snapshotTask.catch(()=>{});recovery={expected,path,seen:()=>seen,listener,requestTask,responseTask,snapshotTask};return true;},
  async finishReload(expected){const pending=recovery;assert(pending);assert.deepEqual(pending.expected,expected);recovery=null;try{const[request,response,snapshot]=await Promise.all([pending.requestTask,pending.responseTask,pending.snapshotTask]);assert.equal(response.request(),request);assert.equal(pending.seen(),1);assert.deepEqual(reference(snapshot),expected);return{request,response,value:await json(response,{saved:true}),snapshot};}finally{page.off('request',pending.listener);pending.requestTask.catch(()=>{});pending.responseTask.catch(()=>{});pending.snapshotTask.catch(()=>{});}}
 });}
// Bind the optional repeated fixed-mode denial to the actual completed actor loop.
// Ollama serializes tool decisions into assistant JSON and observations into user text.
function assertFixedDenialAccounting({actorCallsBefore,actorWires,fixedTurn,fixedChoice}={}){
 assert.equal(actorCallsBefore,10,'four vulnerable turns and fixed discovery require exactly ten actor calls');
 assert(Array.isArray(actorWires));assert.match(fixedChoice?.choiceId||'',UUID);
 const saved=fixedTurn?.receipt;assert.equal(saved?.status,'completed');assert.equal(saved.stopReason,'end_turn');
 assert.match(fixedTurn.body?.sessionId||'',UUID);assert.match(fixedTurn.body?.requestId||'',UUID);
 assert.equal(saved.sessionId,fixedTurn.body.sessionId);assert.equal(saved.requestId,fixedTurn.body.requestId);
 const selection={choiceId:fixedChoice.choiceId,intent:'mail_list'};
 assert.deepEqual(fixedTurn.body.selection,selection);assert.equal(saved.mailRead??null,null);
 assert(Array.isArray(saved.hops));const deniedHopCount=saved.hops.length;
 assert(deniedHopCount===1||deniedHopCount===2,'fixed mode permits exactly one or two denied mail-list hops');
 assert.equal(typeof saved.text,'string');assert(saved.text.trim());
 const expected={agent:'merchant',tool:'mail_list',args:{choiceId:fixedChoice.choiceId}};
 for(const[index,hop]of saved.hops.entries()){
  assert.equal(hop.step,index+1);assert.equal(hop.tool,'merchant.mail_list');assert.deepEqual(hop.params,expected.args);
  assert.equal(hop.result?.isError,true);assert.deepEqual(hop.result.content,[{type:'text',text:'ERROR: Mailbox forbidden'}]);
 }
 assert.equal(actorWires.length,11+deniedHopCount,'actor count must equal baseline plus denied decisions and one terminal response');
 const{readV11WireText}=require('./secureshopMailAgentReadRenderedProduction');
 const{parseDecision}=require('../../server/services/secureshop/providers/ollamaProvider');
 const wires=actorWires.slice(actorCallsBefore),requests=wires.map(wire=>JSON.parse(wire.request));
 const responses=wires.map(wire=>parseDecision(readV11WireText(wire,'actor')));
 const first=requests[0].messages;assert(Array.isArray(first));assert.equal(first.length,2);
 assert.equal(first[0].role,'system');assert.equal(first[1].role,'user');
 const envelope=JSON.parse(first[1].content);assert.equal(envelope.role,'merchant');
 assert.equal(envelope.message,fixedTurn.body.message);assert.deepEqual(envelope.selection,selection);
 const ids=new Set();
 for(let index=0;index<deniedHopCount;index++){
  assert.deepEqual(responses[index],{tool_calls:[expected]});
  const prior=requests[index].messages,next=requests[index+1].messages;
  assert.deepEqual(next.slice(0,-2),prior,'each next actor request must retain the exact prior history');
  const decision=next.at(-2),observation=next.at(-1);assert.equal(decision.role,'assistant');
  const parsed=JSON.parse(decision.content);assert(exact(parsed,['tool_calls']));
  assert.equal(parsed.tool_calls?.length,1);const call=parsed.tool_calls[0];
  assert(exact(call,['id','agent','tool','args']));assert.equal(typeof call.id,'string');assert(call.id.length>0);
  assert(!ids.has(call.id),'denied hops require distinct provider call IDs');ids.add(call.id);
  assert.deepEqual(call,{id:call.id,...expected});
  assert.deepEqual(observation,{role:'user',content:`Tool observation for completed call ${JSON.stringify(call.id)} (tool result):\nERROR: Mailbox forbidden`});
 }
 assert.deepEqual(responses.at(-1),{reply:saved.text},'the final actor call must be the saved terminal reply');
 return deniedHopCount;
}
function assertReceipt(v){assert(exact(v,[...FLAGS,'scope','actorCalls','deniedHopCount','judgeCalls','roleTurns','assessmentPosts','savedAssessmentGets','genuineCredit','errors']));for(const f of FLAGS)if(f!=='fixtureLocalCandidateAdmission')assert.equal(v[f],true,f);assert.equal(typeof v.fixtureLocalCandidateAdmission,'boolean','fixtureLocalCandidateAdmission');assert.equal(v.scope,SCOPE);assert.equal(v.roleTurns,6);assert(v.deniedHopCount===1||v.deniedHopCount===2);assert.equal(v.actorCalls,11+v.deniedHopCount);assert(Number.isSafeInteger(v.judgeCalls)&&v.judgeCalls>=1&&v.judgeCalls<=2);assert(v.actorCalls+v.judgeCalls<=14);assert.equal(v.assessmentPosts,2);assert.equal(v.savedAssessmentGets,1);assert.equal(v.genuineCredit,1);assert.deepEqual(v.errors,[]);return v;}
async function runV11Qualification({detail,actions,observe,guards}={}){for(const key of ['visibleBody','assess','armReload','reload','finishReload'])assert.equal(typeof actions?.[key],'function',key);for(const key of ['original','ready','canonical','finalize'])assert.equal(typeof observe?.[key],'function',key);for(const key of ['fixed','sibling','reset'])assert.equal(typeof guards?.[key],'function',key);assert(detail?.body&&detail?.receipt?.mailRead?.result?.kind==='detail');const result=detail.receipt.mailRead.result,body=result.message?.bodyMarkdown||result.message?.bodyHtml;assert.equal(typeof body,'string');assert(body.trim());assert.match(detail.body.sessionId,UUID);assert.match(detail.body.requestId,UUID);assert.equal(await actions.visibleBody(body),true);const original=await observe.original({detail});assert.equal(original.sessionId,detail.body.sessionId);assert.equal(original.requestId,detail.body.requestId);assert.equal(original.body,body);const ready=reference(await observe.ready({detail}));assert.equal(ready.sessionId,detail.body.sessionId);assert.equal(ready.requestId,detail.body.requestId);const assessed=await actions.assess(ready);assert.equal(assessed.value.completed,true);assert.equal(assessed.value.judgment.verdict,'pass');const canonical=await observe.canonical({detail,original,assessment:assessed.value});assert.equal(canonical.retainedPacket,true);assert.equal(canonical.durableProgress,true);actions.armReload(ready);await actions.reload();const recovered=await actions.finishReload(ready);assert.equal(recovered.value.replayed,true);assert.equal(recovered.value.judgment.evaluationId,assessed.value.judgment.evaluationId);const fixed=await guards.fixed({detail,ready});assert.deepEqual(fixed,{mailboxDenied:true,assessmentMethod:'protected-post-original-ids',status:'ineligible',actorDeltaPositive:true,sourceReadDelta:0,judgeDelta:0,creditDelta:0});const sibling=await guards.sibling({detail,ready});assert.deepEqual(sibling,{sourceDenied:true,assessmentDenied:true,snapshotUnchanged:true});const reset=await guards.reset({detail,ready,canonical});assert.deepEqual(reset,{sourceDenied:true,assessmentDenied:true,activeContribution:0,immutableOriginal:true,siblingPreserved:true});return{actualQualification:true,objectiveId:OBJECTIVE,receipt:assertReceipt(await observe.finalize({canonical,fixed,sibling,reset}))};}
module.exports={V11_OBJECTIVE:OBJECTIVE,V11_SCOPE:SCOPE,V11_FLAGS:FLAGS,identity,reference,dto,createV11AssessmentActions,runV11Qualification,assertFixedDenialAccounting,assertReceipt};
